def login_page_html(
    oidc_enabled: bool = False,
    oidc_display_name: str = "Corporate SSO",
    local_auth_enabled: bool = True,
    registration_enabled: bool = True,
    error: str = "",
) -> str:
    error_messages = {
        "oidc": "Single sign-on could not be completed. Please try again or contact your administrator.",
        "registration_disabled": "Local account registration is not available on this portal.",
    }
    notice = ""
    if error in error_messages:
        notice = f'<div class="ui-alert ui-alert-error login-error" role="alert"><span>{_icon("alert")}</span><span>{escape(error_messages[error])}</span></div>'

    oidc_block = ""
    if oidc_enabled:
        oidc_block = f'<a id="oidc-login" class="ui-button sso-button w-full" href="/auth/oidc/login">{_icon("shield","icon-sm")} Continue with {escape(oidc_display_name)}</a>'

    local_block = ""
    if local_auth_enabled:
        register_link = '<div class="auth-link-row">Need an account? <a href="/register">Register</a></div>' if registration_enabled else ""
        local_block = f'''
      <form id="login" novalidate>
        <div class="form-field"><label class="ui-label" for="username">Username</label><input class="ui-input" id="username" name="username" autocomplete="username" placeholder="Enter your username" required></div>
        <div class="form-field"><label class="ui-label" for="password">Password</label><div class="password-wrap"><input class="ui-input" id="password" name="password" type="password" autocomplete="current-password" placeholder="Enter your password" required><button id="toggle-password" class="ui-icon-button password-toggle" type="button" aria-label="Show password">{_icon("eye")}</button></div></div>
        <div id="login-error" class="ui-alert ui-alert-error login-error hidden" role="alert"><span>{_icon("alert")}</span><span id="login-error-text">Unable to sign in.</span></div>
        <button id="login-button" class="ui-button ui-button-primary w-full" style="margin-top:1rem" type="submit"><span id="login-spinner" class="ui-spinner hidden"></span><span id="login-button-text">Sign in</span></button>
      </form>{register_link}'''

    divider = '<div class="auth-divider"><span>or use a local account</span></div>' if oidc_enabled and local_auth_enabled else ""
    provider_note = '<div class="provider-note">Authentication is delegated to your organization identity provider.</div>' if oidc_enabled and not local_auth_enabled else ""
    local_script = ""
    if local_auth_enabled:
        local_script = r'''
const form=document.getElementById('login'),button=document.getElementById('login-button'),spinner=document.getElementById('login-spinner'),buttonText=document.getElementById('login-button-text'),errorBox=document.getElementById('login-error'),errorText=document.getElementById('login-error-text');
document.getElementById('toggle-password').addEventListener('click',()=>{const p=document.getElementById('password'); const reveal=p.type==='password'; p.type=reveal?'text':'password'; document.getElementById('toggle-password').setAttribute('aria-label',reveal?'Hide password':'Show password');});
form.addEventListener('submit',async(e)=>{e.preventDefault(); errorBox.classList.add('hidden'); if(!form.reportValidity()) return; button.disabled=true; spinner.classList.remove('hidden'); buttonText.textContent='Signing in…'; try{const r=await fetch('/auth/login',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({username:document.getElementById('username').value.trim(),password:document.getElementById('password').value})}); if(!r.ok){let msg='Unable to sign in. Check your credentials and try again.'; try{const j=await r.json(); if(j.detail) msg=typeof j.detail==='string'?j.detail:msg}catch(_){} throw new Error(msg)} window.location.assign('/dashboard')}catch(err){errorText.textContent=err.message; errorBox.classList.remove('hidden'); button.disabled=false; spinner.classList.add('hidden'); buttonText.textContent='Sign in'; document.getElementById('password').focus();}});
'''

    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in · OpenCode Workspace Portal</title><link rel="stylesheet" href="/_ui/app.css"></head>
<body><main class="login-shell">
  <section class="login-visual" aria-hidden="true"><div class="login-brand"><span class="brand-mark">{_icon("terminal")}</span><div>OpenCode Workspace Portal<small>Internal developer platform</small></div></div><div class="login-hero"><span class="login-kicker"><span class="status-dot"></span> Secure multi-user workspace gateway</span><h1>Developer workspaces, isolated and ready on demand.</h1><p>Launch persistent OpenCode environments without managing containers, credentials, or runtime cleanup manually.</p><div class="feature-list"><div class="feature-item">{_icon("shield")}<strong>Enterprise identity</strong><span>Use OpenID Connect SSO or optional local portal accounts.</span></div><div class="feature-item">{_icon("database")}<strong>Persistent state</strong><span>Your projects and OpenCode sessions survive runtime recreation.</span></div><div class="feature-item">{_icon("refresh")}<strong>Automatic cleanup</strong><span>Idle runtimes are reclaimed while workspace data remains available.</span></div></div></div><div class="login-foot">OpenCode Multiuser v{escape(__version__)} · Enterprise workspace gateway</div></section>
  <section class="login-panel app-grid-bg"><div class="ui-card ui-card-elevated login-card"><div style="display:flex;align-items:center;gap:.75rem;margin-bottom:1.2rem"><span class="brand-mark">{_icon("terminal")}</span><div><strong style="display:block;font-size:.9rem">OpenCode</strong><span class="text-xs text-muted">Workspace Portal</span></div></div><h2>Welcome back</h2><p>Sign in to access your isolated development workspaces.</p>{notice}<div class="auth-stack">{oidc_block}</div>{divider}{local_block}{provider_note}<div class="login-meta">{_icon("shield","icon-sm")} <span>Secure internal access · Session protected</span></div></div></section>
</main><script>{local_script}</script></body></html>'''


def registration_page_html(first_user: bool = False) -> str:
    role_note = (
        '<div class="ui-alert ui-alert-success registration-note"><span>' + _icon("shield") + '</span><span><strong>Bootstrap administrator</strong>This is the first account. It will receive the Admin role.</span></div>'
        if first_user
        else '<div class="ui-alert registration-note"><span>' + _icon("user") + '</span><span>New local accounts receive the Developer role.</span></div>'
    )
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register · OpenCode Workspace Portal</title><link rel="stylesheet" href="/_ui/app.css"></head><body><main class="login-shell"><section class="login-visual" aria-hidden="true"><div class="login-brand"><span class="brand-mark">{_icon("terminal")}</span><div>OpenCode Workspace Portal<small>Internal developer platform</small></div></div><div class="login-hero"><span class="login-kicker"><span class="status-dot"></span> Local portal account</span><h1>Create your developer portal account.</h1><p>Use a strong password. Workspace runtime credentials remain isolated from this portal account.</p></div><div class="login-foot">OpenCode Multiuser v{escape(__version__)} · Enterprise workspace gateway</div></section><section class="login-panel app-grid-bg"><div class="ui-card ui-card-elevated login-card"><div style="display:flex;align-items:center;gap:.75rem;margin-bottom:1.2rem"><span class="brand-mark">{_icon("user")}</span><div><strong style="display:block;font-size:.9rem">Create account</strong><span class="text-xs text-muted">Local authentication</span></div></div><h2>Register</h2><p>Create a local account for this OpenCode portal.</p>{role_note}<form id="register" novalidate><div class="form-field"><label class="ui-label" for="username">Username</label><input class="ui-input" id="username" autocomplete="username" pattern="[A-Za-z0-9_.-]+" minlength="3" maxlength="80" required placeholder="e.g. cahya"></div><div class="form-field"><label class="ui-label" for="password">Password</label><input class="ui-input" id="password" type="password" autocomplete="new-password" minlength="12" required placeholder="At least 12 characters"></div><div class="form-field"><label class="ui-label" for="confirm">Confirm password</label><input class="ui-input" id="confirm" type="password" autocomplete="new-password" minlength="12" required placeholder="Repeat your password"></div><div id="register-error" class="ui-alert ui-alert-error login-error hidden" role="alert"><span>{_icon("alert")}</span><span id="register-error-text"></span></div><button id="register-button" class="ui-button ui-button-primary w-full" style="margin-top:1rem" type="submit"><span id="register-spinner" class="ui-spinner hidden"></span><span id="register-button-text">Create account</span></button></form><div class="auth-link-row">Already have an account? <a href="/login">Sign in</a></div></div></section></main><script>const form=document.getElementById('register'),button=document.getElementById('register-button'),spinner=document.getElementById('register-spinner'),text=document.getElementById('register-button-text'),box=document.getElementById('register-error'),err=document.getElementById('register-error-text');form.addEventListener('submit',async e=>{{e.preventDefault();box.classList.add('hidden');if(!form.reportValidity())return;const password=document.getElementById('password').value;if(password!==document.getElementById('confirm').value){{err.textContent='Passwords do not match.';box.classList.remove('hidden');return}}button.disabled=true;spinner.classList.remove('hidden');text.textContent='Creating account…';try{{const r=await fetch('/auth/register',{{method:'POST',headers:{{'content-type':'application/json'}},credentials:'same-origin',body:JSON.stringify({{username:document.getElementById('username').value.trim(),password}})}});if(!r.ok){{let msg='Unable to create account.';try{{const j=await r.json();if(j.detail)msg=typeof j.detail==='string'?j.detail:msg}}catch(_){{}}throw new Error(msg)}}window.location.assign('/dashboard')}}catch(e){{err.textContent=e.message;box.classList.remove('hidden');button.disabled=false;spinner.classList.add('hidden');text.textContent='Create account'}}}});</script></body></html>'''


def dashboard_page_html(username: str, notice_html: str, max_slots: int, free_slots: int, idle_minutes: int, role: str = "developer", display_name: str | None = None) -> str:
    safe_user = escape(username)
    safe_name = escape(display_name or username)
    safe_role = escape(role or "developer")
    initials = escape(((display_name or username)[:2] or "U").upper())
    admin_link = f'<a class="ui-button ui-button-ghost" href="/admin/users">{_icon("shield","icon-sm")} Admin</a>' if role == "admin" else ""
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Workspaces · OpenCode</title><link rel="stylesheet" href="/_ui/app.css"></head>
<body class="app-grid-bg">
<header class="topbar"><div class="topbar-inner"><a class="topbar-brand" href="/dashboard"><span class="brand-mark">{_icon("terminal")}</span><div><strong>OpenCode</strong><span>Workspace Portal · v{escape(__version__)}</span></div></a><div class="user-menu">{admin_link}<div class="user-chip"><span class="avatar">{initials}</span><span>{safe_name}</span><span class="role-badge">{safe_role}</span></div><form id="logout-form" method="post" action="/logout"><button class="ui-button ui-button-ghost" type="submit">{_icon("logout","icon-sm")} Logout</button></form></div></div></header>
<main class="dashboard-main">
  <div class="dashboard-heading"><div><div class="eyebrow">{_icon("layers","icon-sm")} Developer platform</div><h1>Your workspaces</h1><p>Start, resume, and manage isolated OpenCode development environments.</p></div><div class="platform-state"><span class="status-dot"></span> Platform online</div></div>
  {notice_html}
  <section class="stats-grid" aria-label="Workspace statistics">
    <div class="ui-card stat-card"><div class="stat-head"><span>Projects</span><span class="stat-icon">{_icon("layers","icon-sm")}</span></div><div id="stat-projects" class="stat-value">—</div><div class="stat-sub">Visible to your account</div></div>
    <div class="ui-card stat-card"><div class="stat-head"><span>Running</span><span class="stat-icon">{_icon("activity","icon-sm")}</span></div><div id="stat-running" class="stat-value">—</div><div class="stat-sub">Active workspace runtimes</div></div>
    <div class="ui-card stat-card"><div class="stat-head"><span>Available slots</span><span class="stat-icon">{_icon("server","icon-sm")}</span></div><div id="stat-free" class="stat-value">{free_slots}</div><div class="stat-sub">of {max_slots} total runtime slots</div></div>
    <div class="ui-card stat-card"><div class="stat-head"><span>Idle timeout</span><span class="stat-icon">{_icon("clock","icon-sm")}</span></div><div class="stat-value">{idle_minutes}<span style="font-size:.8rem;font-weight:700;color:#64748b;margin-left:.15rem">min</span></div><div class="stat-sub">Unused runtimes are reclaimed</div></div>
  </section>
  <section class="ui-card start-panel">
    <div class="start-title"><span class="workspace-icon" style="width:32px;height:32px">{_icon("plus","icon-sm")}</span><span>Start a workspace</span></div>
    <form id="new" class="start-row"><div class="start-field"><label class="ui-label" for="project">Project slug</label><input class="ui-input" id="project" required pattern="[A-Za-z0-9_.-]+" placeholder="e.g. agentic-ai-platform" autocomplete="off"></div><button id="start-new" class="ui-button ui-button-primary" type="submit">{_icon("play","icon-sm")} Start workspace</button><div class="start-help">Letters, numbers, dots, underscores, and hyphens only. Existing project data will be reused automatically.</div></form>
  </section>
  <div class="section-head"><div><h2>Projects & workspaces</h2><span>Runtime state and available actions</span></div><button id="refresh-button" class="ui-button ui-button-secondary" type="button">{_icon("refresh","icon-sm")} Refresh</button></div>
