<script>
const busy=document.getElementById('busy'),busyTitle=document.getElementById('busy-title'),busyDetail=document.getElementById('busy-detail'),list=document.getElementById('list'),toasts=document.getElementById('toasts');let pendingStop=null,pendingRemove=null,busyTimer=null;
function esc(v){{return String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]))}}
function toast(title,message,type='success'){{const el=document.createElement('div');el.className='toast '+type;el.innerHTML=`<span>${{type==='error'?'⚠':'✓'}}</span><div><div class="toast-title">${{esc(title)}}</div><div class="toast-message">${{esc(message)}}</div></div>`;toasts.appendChild(el);setTimeout(()=>el.remove(),4500)}}
function setBusy(title,detail,stages=[]){{busyTitle.textContent=title;busyDetail.textContent=detail;busy.hidden=false;document.querySelectorAll('button').forEach(b=>b.disabled=true);if(busyTimer)clearInterval(busyTimer);let i=0;if(stages.length){{busyDetail.textContent=stages[0];busyTimer=setInterval(()=>{{i=Math.min(i+1,stages.length-1);busyDetail.textContent=stages[i];}},1700)}}}}
function hideBusy(){{busy.hidden=true;document.querySelectorAll('button').forEach(b=>b.disabled=false);if(busyTimer)clearInterval(busyTimer);busyTimer=null}}
async function api(url,opts={{}}){{const r=await fetch(url,{{credentials:'same-origin',...opts}});if(!r.ok){{let msg=r.statusText;try{{const j=await r.json();msg=typeof j.detail==='string'?j.detail:(j.detail?.message||JSON.stringify(j.detail))}}catch(_){{}}throw new Error(msg)}}return r.status===204?null:r.json()}}
function badge(status){{const s=(status||'unknown').toLowerCase();return `<span class="ui-badge badge-${{esc(s)}}">${{esc(s)}}</span>`}}
function workspaceCard(w){{const running=w.status==='running',legacy=running&&!w.url,stopped=w.status==='stopped'||w.status==='error';const c=document.createElement('article');c.className='ui-card workspace-card';c.innerHTML=`<div class="workspace-card-head"><span class="workspace-icon">${{`{_icon("code")}`}}</span>${{badge(w.status)}}</div><h3>${{esc(w.project_slug)}}</h3><div class="workspace-sub">${{running?'Runtime available and ready for use.':w.status==='error'?'The last runtime failed. Start it again to retry.':'Persistent workspace data is available.'}}</div><div class="workspace-meta"><span class="meta-pill">Slot ${{esc(w.slot_id??'—')}}</span>${{w.container_name?`<span class="meta-pill" title="${{esc(w.container_name)}}">${{esc(w.container_name)}}</span>`:''}}</div><div class="workspace-actions"></div>`;const actions=c.querySelector('.workspace-actions');if(running&&w.url){{const a=document.createElement('a');a.className='ui-button ui-button-primary';a.href=w.url;a.innerHTML=`{_icon("external","icon-sm")} Open`;actions.appendChild(a);const b=document.createElement('button');b.className='ui-button ui-button-secondary';b.type='button';b.innerHTML=`{_icon("stop","icon-sm")} Stop`;b.onclick=()=>askStop(w);actions.appendChild(b)}}else if(legacy){{const b=document.createElement('button');b.className='ui-button ui-button-primary';b.type='button';b.innerHTML=`{_icon("refresh","icon-sm")} Upgrade runtime`;b.onclick=()=>startProject(w.project_slug);actions.appendChild(b)}}else if(stopped){{const b=document.createElement('button');b.className='ui-button ui-button-primary';b.type='button';b.innerHTML=`{_icon("play","icon-sm")} Start`;b.onclick=()=>startProject(w.project_slug);actions.appendChild(b)}}const remove=document.createElement('button');remove.className='ui-button ui-button-danger';remove.type='button';remove.innerHTML=`{_icon("x","icon-sm")} Remove`;remove.onclick=()=>askRemove(w);actions.appendChild(remove);return c}}
async function refresh(silent=false){{if(!silent)document.getElementById('refresh-button').disabled=true;try{{const rows=await api('/workspaces');list.innerHTML='';document.getElementById('stat-projects').textContent=rows.length;document.getElementById('stat-running').textContent=rows.filter(w=>w.status==='running').length;if(!rows.length){{list.innerHTML=`<div class="ui-card empty-state"><div class="empty-icon">{_icon("code")}</div><h3>No workspaces yet</h3><p>Start your first project above. A dedicated OpenCode runtime will be created and connected automatically.</p></div>`}}else rows.forEach(w=>list.appendChild(workspaceCard(w)));try{{const o=await api('/_portal/overview');document.getElementById('stat-free').textContent=o.free_slots}}catch(_){{}}}}catch(err){{list.innerHTML=`<div class="ui-card empty-state"><div class="empty-icon" style="color:#dc2626;background:#fef2f2">{_icon("alert")}</div><h3>Unable to load workspaces</h3><p>${{esc(err.message)}}</p></div>`;toast('Unable to refresh',err.message,'error')}}finally{{document.getElementById('refresh-button').disabled=false}}}}
async function startProject(slug){{setBusy('Starting workspace…','Starting container…',['Starting container…','Waiting for OpenCode service…','Finalizing secure gateway…','Opening workspace…']);try{{const x=await api('/workspaces/start',{{method:'POST',headers:{{'content-type':'application/json'}},body:JSON.stringify({{project_slug:slug}})}});busyDetail.textContent='Opening workspace…';window.location.assign(x.url)}}catch(err){{hideBusy();toast('Workspace failed to start',err.message,'error');await refresh(true)}}}}
function askStop(w){{pendingStop=w;document.getElementById('stop-dialog-text').textContent=`Stop ${{w.project_slug}}? The runtime container will be stopped and its slot freed. Your persistent workspace data will be kept.`;document.getElementById('stop-dialog').showModal()}}
async function stopProject(w){{setBusy('Stopping workspace…','Stopping container…',['Stopping container…','Freeing runtime slot…','Updating workspace status…']);try{{await api('/workspaces/'+w.id+'/stop',{{method:'POST'}});hideBusy();toast('Workspace stopped',`${{w.project_slug}} is stopped and its slot is now available.`);await refresh(true)}}catch(err){{hideBusy();toast('Unable to stop workspace',err.message,'error')}}}}
function askRemove(w){{pendingRemove=w;document.getElementById('remove-dialog-text').textContent=`Remove ${{w.project_slug}} permanently? Its runtime, project files, and OpenCode data will be deleted and cannot be recovered.`;document.getElementById('remove-dialog').showModal()}}
async function removeProject(w){{setBusy('Removing workspace…','Stopping runtime and deleting persistent data…',['Stopping runtime…','Deleting project files…','Deleting OpenCode data…']);try{{await api('/workspaces/'+w.id,{{method:'DELETE'}});hideBusy();toast('Workspace removed',`${{w.project_slug}} and its persistent data were permanently deleted.`);await refresh(true)}}catch(err){{hideBusy();toast('Unable to remove workspace',err.message,'error')}}}}
document.getElementById('new').addEventListener('submit',e=>{{e.preventDefault();if(!e.currentTarget.reportValidity())return;startProject(document.getElementById('project').value.trim())}});document.getElementById('refresh-button').onclick=()=>refresh();document.getElementById('stop-cancel').onclick=()=>document.getElementById('stop-dialog').close();document.getElementById('stop-confirm').onclick=()=>{{document.getElementById('stop-dialog').close();if(pendingStop)stopProject(pendingStop)}};document.getElementById('remove-cancel').onclick=()=>document.getElementById('remove-dialog').close();document.getElementById('remove-confirm').onclick=()=>{{document.getElementById('remove-dialog').close();if(pendingRemove)removeProject(pendingRemove)}};
document.getElementById('logout-form').addEventListener('submit',async e=>{{e.preventDefault();setBusy('Logging out…','Stopping active workspaces…',['Stopping active workspaces…','Freeing runtime slots…','Ending your session…']);try{{await fetch('/logout',{{method:'POST',credentials:'same-origin'}});window.location.assign('/login')}}catch(err){{hideBusy();toast('Logout failed',err.message,'error')}}}});
refresh();
</script></body></html>'''


def admin_users_page_html(username: str, display_name: str | None = None) -> str:
    safe_name = escape(display_name or username)
    initials = escape(((display_name or username)[:2] or "A").upper())
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>User management · OpenCode</title><link rel="stylesheet" href="/_ui/app.css"></head>
