    <div class="ui-card stat-card"><div class="stat-head"><span>Active users</span><span class="stat-icon">{_icon("activity","icon-sm")}</span></div><div id="admin-stat-active" class="stat-value">—</div><div class="stat-sub">Accounts allowed to sign in</div></div>
