<script>
const tbody=document.getElementById('admin-users'),toasts=document.getElementById('toasts'),busy=document.getElementById('busy'),busyTitle=document.getElementById('busy-title'),busyDetail=document.getElementById('busy-detail');let users=[],passwordTarget=null,deleteTarget=null;
function esc(v){{return String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]))}}
function fmt(v){{if(!v)return 'Never';try{{return new Intl.DateTimeFormat(undefined,{{dateStyle:'medium',timeStyle:'short'}}).format(new Date(v))}}catch(_){{return v}}}}
function toast(title,message,type='success'){{const el=document.createElement('div');el.className='toast '+type;el.innerHTML=`<span>${{type==='error'?'⚠':'✓'}}</span><div><div class="toast-title">${{esc(title)}}</div><div class="toast-message">${{esc(message)}}</div></div>`;toasts.appendChild(el);setTimeout(()=>el.remove(),4500)}}
function setBusy(title,detail){{busyTitle.textContent=title;busyDetail.textContent=detail;busy.hidden=false;document.querySelectorAll('button,select').forEach(x=>x.disabled=true)}}function hideBusy(){{busy.hidden=true;document.querySelectorAll('button,select').forEach(x=>x.disabled=false)}}
async function api(url,opts={{}}){{const r=await fetch(url,{{credentials:'same-origin',...opts}});if(!r.ok){{let msg=r.statusText;try{{const j=await r.json();msg=typeof j.detail==='string'?j.detail:(j.detail?.message||JSON.stringify(j.detail))}}catch(_){{}}throw new Error(msg)}}return r.status===204?null:r.json()}}
function workspaceHtml(u){{if(!u.active_workspaces.length)return '<span class="text-muted">None</span>';return `<div class="workspace-stack">${{u.active_workspaces.map(w=>`<div class="workspace-mini"><span class="status-dot"></span><span>${{esc(w.project_slug)}}</span><span class="text-muted">slot ${{esc(w.slot_id??'—')}}</span></div>`).join('')}}</div>`}}
function row(u){{const tr=document.createElement('tr');const provider=u.auth_provider==='oidc'?'<span class="provider-badge provider-oidc">OIDC</span>':'<span class="provider-badge">Local</span>';const state=u.is_active?'<span class="state-pill state-active">Active</span>':'<span class="state-pill state-disabled">Disabled</span>';const role=`<span class="role-pill ${{u.role==='admin'?'role-admin':''}}">${{esc(u.role)}}</span>`;const localReset=u.auth_provider==='local'?`<button class="ui-button ui-button-secondary ui-button-xs" data-action="password">Reset password</button>`:'';const stop=u.active_workspaces.length?`<button class="ui-button ui-button-secondary ui-button-xs" data-action="stop">Stop workspaces</button>`:'';const del=u.can_delete?`<button class="ui-button ui-button-danger ui-button-xs" data-action="delete">Delete</button>`:'';const toggle=u.is_self?'':`<button class="ui-button ui-button-secondary ui-button-xs" data-action="toggle">${{u.is_active?'Disable':'Enable'}}</button>`;const roleSelect=u.is_self?role:`<select class="admin-select" data-action="role"><option value="developer" ${{u.role==='developer'?'selected':''}}>Developer</option><option value="admin" ${{u.role==='admin'?'selected':''}}>Admin</option></select>`;tr.innerHTML=`<td data-label="User"><div class="user-cell"><span class="avatar">${{esc((u.display_name||u.username).slice(0,2).toUpperCase())}}</span><div><div class="user-primary">${{esc(u.display_name||u.username)}} ${{u.is_self?'<span class="text-xs text-muted">(you)</span>':''}}</div><div class="user-secondary">${{esc(u.username)}}${{u.email?' · '+esc(u.email):''}}</div></div></div></td><td data-label="Auth">${{provider}}</td><td data-label="Role">${{roleSelect}}</td><td data-label="Last login">${{esc(fmt(u.last_login_at))}}</td><td data-label="Created">${{esc(fmt(u.created_at))}}</td><td data-label="Workspaces">${{workspaceHtml(u)}}</td><td data-label="Status">${{state}}</td><td data-label="Actions"><div class="admin-actions">${{stop}}${{toggle}}${{localReset}}${{del}}</div></td>`;tr.querySelectorAll('[data-action]').forEach(el=>{{const a=el.dataset.action;if(a==='role')el.onchange=()=>changeRole(u,el.value);if(a==='toggle')el.onclick=()=>toggleUser(u);if(a==='stop')el.onclick=()=>stopWorkspaces(u);if(a==='password')el.onclick=()=>openPassword(u);if(a==='delete')el.onclick=()=>openDelete(u)}});return tr}}
function render(){{const q=document.getElementById('user-search').value.toLowerCase().trim(),rf=document.getElementById('role-filter').value,sf=document.getElementById('status-filter').value;const filtered=users.filter(u=>{{const text=[u.username,u.display_name,u.email].filter(Boolean).join(' ').toLowerCase();return(!q||text.includes(q))&&(!rf||u.role===rf)&&(!sf||(sf==='active'?u.is_active:!u.is_active))}});tbody.innerHTML='';if(!filtered.length){{tbody.innerHTML='<tr><td colspan="8"><div class="admin-empty">No users match the current filters.</div></td></tr>';return}}filtered.forEach(u=>tbody.appendChild(row(u)))}}
async function refresh(){{document.getElementById('refresh-admin').disabled=true;try{{const data=await api('/api/admin/users');users=data.users;document.getElementById('admin-stat-total').textContent=data.summary.total_users;document.getElementById('admin-stat-admins').textContent=data.summary.enabled_admins;document.getElementById('admin-stat-active').textContent=data.summary.active_users;document.getElementById('admin-stat-workspaces').textContent=data.summary.running_workspaces;render()}}catch(e){{toast('Unable to load users',e.message,'error')}}finally{{document.getElementById('refresh-admin').disabled=false}}}}
async function changeRole(u,role){{if(role===u.role)return;setBusy('Updating role…',`Changing ${{u.username}} to ${{role}}.`);try{{await api('/api/admin/users/'+u.id+'/role',{{method:'PATCH',headers:{{'content-type':'application/json'}},body:JSON.stringify({{role}})}});hideBusy();toast('Role updated',`${{u.username}} is now ${{role}}.`);await refresh()}}catch(e){{hideBusy();toast('Role change rejected',e.message,'error');await refresh()}}}}
async function toggleUser(u){{setBusy(u.is_active?'Disabling account…':'Enabling account…',u.is_active?'Stopping active runtimes and blocking future sign-in.':'Restoring sign-in access.');try{{await api('/api/admin/users/'+u.id+'/status',{{method:'PATCH',headers:{{'content-type':'application/json'}},body:JSON.stringify({{is_active:!u.is_active}})}});hideBusy();toast('Account updated',`${{u.username}} is now ${{u.is_active?'disabled':'enabled'}}.`);await refresh()}}catch(e){{hideBusy();toast('Account update rejected',e.message,'error');await refresh()}}}}
async function stopWorkspaces(u){{setBusy('Stopping workspaces…',`Freeing runtime slots owned by ${{u.username}}.`);try{{const r=await api('/api/admin/users/'+u.id+'/stop-workspaces',{{method:'POST'}});hideBusy();toast('Workspaces stopped',`${{r.stopped}} runtime(s) stopped and slots freed.`);await refresh()}}catch(e){{hideBusy();toast('Unable to stop workspaces',e.message,'error')}}}}
function openPassword(u){{passwordTarget=u;document.getElementById('password-dialog-user').textContent=`Set a new local password for ${{u.username}}.`;document.getElementById('new-password').value='';document.getElementById('password-dialog').showModal();setTimeout(()=>document.getElementById('new-password').focus(),0)}}
async function resetPassword(){{const p=document.getElementById('new-password').value;if(p.length<12){{toast('Password too short','Use at least 12 characters.','error');return}}document.getElementById('password-dialog').close();setBusy('Resetting password…',`Updating local credentials for ${{passwordTarget.username}}.`);try{{await api('/api/admin/users/'+passwordTarget.id+'/password',{{method:'POST',headers:{{'content-type':'application/json'}},body:JSON.stringify({{password:p}})}});hideBusy();toast('Password reset','The new password is active immediately.')}}catch(e){{hideBusy();toast('Password reset failed',e.message,'error')}}}}
function openDelete(u){{deleteTarget=u;document.getElementById('delete-dialog-user').textContent=`Delete local account ${{u.username}}? Only accounts with no workspace history can be deleted.`;document.getElementById('delete-dialog').showModal()}}
async function deleteUser(){{document.getElementById('delete-dialog').close();setBusy('Deleting account…',`Removing ${{deleteTarget.username}} from the portal.`);try{{await api('/api/admin/users/'+deleteTarget.id,{{method:'DELETE'}});hideBusy();toast('Account deleted',`${{deleteTarget.username}} was removed.`);await refresh()}}catch(e){{hideBusy();toast('Delete rejected',e.message,'error')}}}}
document.getElementById('refresh-admin').onclick=refresh;document.getElementById('user-search').oninput=render;document.getElementById('role-filter').onchange=render;document.getElementById('status-filter').onchange=render;document.getElementById('password-cancel').onclick=()=>document.getElementById('password-dialog').close();document.getElementById('password-confirm').onclick=resetPassword;document.getElementById('delete-cancel').onclick=()=>document.getElementById('delete-dialog').close();document.getElementById('delete-confirm').onclick=deleteUser;
document.getElementById('logout-form').addEventListener('submit',async e=>{{e.preventDefault();setBusy('Logging out…','Stopping your active workspaces and ending the session.');try{{await fetch('/logout',{{method:'POST',credentials:'same-origin'}});window.location.assign('/login')}}catch(e){{hideBusy();toast('Logout failed',e.message,'error')}}}});
refresh();
</script></body></html>'''


def admin_system_page_html(username: str, display_name: str | None = None) -> str:
    safe_name = escape(display_name or username)
    initials = escape(((display_name or username)[:2] or "A").upper())
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>System · OpenCode</title><link rel="stylesheet" href="/_ui/app.css"></head>
<body class="app-grid-bg">
<header class="topbar"><div class="topbar-inner"><a class="topbar-brand" href="/dashboard"><span class="brand-mark">{_icon("terminal")}</span><div><strong>OpenCode</strong><span>Workspace Portal · v{escape(__version__)}</span></div></a><div class="user-menu"><a class="ui-button ui-button-ghost" href="/dashboard">{_icon("layers","icon-sm")} Dashboard</a><a class="ui-button ui-button-ghost" href="/admin/users">{_icon("user","icon-sm")} Users</a><div class="user-chip"><span class="avatar">{initials}</span><span>{safe_name}</span><span class="role-badge">admin</span></div><form id="logout-form" method="post" action="/logout"><button class="ui-button ui-button-ghost" type="submit">{_icon("logout","icon-sm")} Logout</button></form></div></div></header>
<main class="admin-main">
  <div class="admin-heading"><div><div class="eyebrow">{_icon("server","icon-sm")} Administration</div><h1>System & OpenCode</h1><p>Inspect the portal runtime and safely build, test, and activate OpenCode workspace images.</p></div><div class="admin-tools"><button id="refresh-system" class="ui-button ui-button-secondary" type="button">{_icon("refresh","icon-sm")} Refresh</button></div></div>
  <section class="system-grid">
    <div class="ui-card system-card"><h2>Portal</h2><dl class="kv-grid"><dt>Portal version</dt><dd id="portal-version">v{escape(__version__)}</dd><dt>Workspace image</dt><dd id="workspace-image" class="mono">—</dd><dt>Update policy</dt><dd>Running workspaces remain untouched until restarted.</dd></dl></div>
    <div class="ui-card system-card"><h2>OpenCode engine</h2><dl class="kv-grid"><dt>Configured version</dt><dd id="configured-version">—</dd><dt>Installed image</dt><dd id="installed-version">—</dd><dt>Latest upstream</dt><dd id="latest-version">Not checked</dd><dt>Registry</dt><dd id="registry-url" class="mono">—</dd></dl></div>
  </section>
  <section class="ui-card system-update">
    <div class="section-head" style="margin-top:0"><div><h2>Update OpenCode</h2><span>Build a candidate image, smoke-test it, and activate it only after validation succeeds.</span></div></div>
    <div class="system-update-row"><div><label class="ui-label" for="target-version">Target version</label><input id="target-version" class="ui-input" placeholder="e.g. 1.18.31" autocomplete="off"></div><button id="check-latest" class="ui-button ui-button-secondary" type="button">{_icon("refresh","icon-sm")} Check latest</button><button id="update-opencode" class="ui-button ui-button-primary" type="button">{_icon("play","icon-sm")} Build & activate</button></div>
    <p class="system-note">The active <span class="mono">latest</span> image is changed only after the candidate reports the requested version. Existing workspace containers keep their current OpenCode process; stop/start them when you want them to pick up the new image.</p>
    <div id="update-progress" class="system-progress"><span class="status-dot" style="background:#94a3b8;box-shadow:none"></span><span><strong id="update-status">Idle</strong> · <span id="update-message">No update is running.</span></span></div>
    <pre id="update-log" class="system-log">No update log yet.</pre>
  </section>
</main>
<div id="toasts" class="toast-region" aria-live="polite" aria-atomic="true"></div>
<script>
const toasts=document.getElementById('toasts');let pollTimer=null,lastUpdateStatus=null;
function esc(v){{return String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]))}}
function toast(title,message,type='success'){{const el=document.createElement('div');el.className='toast '+type;el.innerHTML=`<span>${{type==='error'?'⚠':'✓'}}</span><div><div class="toast-title">${{esc(title)}}</div><div class="toast-message">${{esc(message)}}</div></div>`;toasts.appendChild(el);setTimeout(()=>el.remove(),5000)}}
async function api(url,opts={{}}){{const r=await fetch(url,{{credentials:'same-origin',...opts}});if(!r.ok){{let msg=r.statusText;try{{const j=await r.json();msg=typeof j.detail==='string'?j.detail:(j.detail?.message||JSON.stringify(j.detail))}}catch(_){{}}throw new Error(msg)}}return r.status===204?null:r.json()}}
function renderUpdate(u){{const previous=lastUpdateStatus;lastUpdateStatus=u.status||'idle';document.getElementById('update-status').textContent=lastUpdateStatus.replaceAll('_',' ');document.getElementById('update-message').textContent=u.message||'';document.getElementById('update-log').textContent=(u.log_tail&&u.log_tail.length)?u.log_tail.join('\\n'):'No update log yet.';const running=!!u.running;document.getElementById('update-opencode').disabled=running;document.getElementById('check-latest').disabled=running;if(running&&!pollTimer)pollTimer=setInterval(refreshStatus,1200);if(!running&&pollTimer){{clearInterval(pollTimer);pollTimer=null}}if(previous&&previous!=='success'&&lastUpdateStatus==='success')setTimeout(()=>refreshSystem(false),0)}}
async function refreshSystem(showToast=false){{try{{const d=await api('/api/admin/system');document.getElementById('portal-version').textContent='v'+d.portal_version;document.getElementById('workspace-image').textContent=d.opencode.workspace_image;document.getElementById('configured-version').textContent=d.opencode.configured_version||'—';document.getElementById('installed-version').textContent=d.opencode.installed_version||'Unavailable';document.getElementById('registry-url').textContent=d.opencode.registry_url;const input=document.getElementById('target-version');if(!input.value)input.value=d.opencode.configured_version||'';renderUpdate(d.opencode.update);if(showToast)toast('System refreshed','Current portal and OpenCode state loaded.')}}catch(e){{toast('Unable to load system state',e.message,'error')}}}}
async function refreshStatus(){{try{{const u=await api('/api/admin/system/opencode/update-status');renderUpdate(u)}}catch(e){{if(pollTimer){{clearInterval(pollTimer);pollTimer=null}}toast('Update status unavailable',e.message,'error')}}}}
async function checkLatest(){{const b=document.getElementById('check-latest');b.disabled=true;b.textContent='Checking…';try{{const d=await api('/api/admin/system/opencode/latest');document.getElementById('latest-version').textContent=d.version;document.getElementById('target-version').value=d.version;toast('Latest OpenCode found','Upstream version '+d.version+' is available.')}}catch(e){{toast('Version check failed',e.message,'error')}}finally{{b.disabled=false;b.innerHTML=`{_icon("refresh","icon-sm")} Check latest`}}}}
async function startUpdate(){{const version=document.getElementById('target-version').value.trim();if(!/^\\d+\\.\\d+\\.\\d+(?:-[0-9A-Za-z.-]+)?(?:\\+[0-9A-Za-z.-]+)?$/.test(version)){{toast('Invalid version','Enter a semantic version such as 1.18.31.','error');return}}if(!confirm(`Build, test, and activate OpenCode ${{version}} for newly started workspaces?`))return;try{{const u=await api('/api/admin/system/opencode/update',{{method:'POST',headers:{{'content-type':'application/json'}},body:JSON.stringify({{version}})}});renderUpdate(u);toast('Update started','The candidate image is being built in the background.')}}catch(e){{toast('Unable to start update',e.message,'error')}}}}
document.getElementById('refresh-system').onclick=()=>refreshSystem(true);document.getElementById('check-latest').onclick=checkLatest;document.getElementById('update-opencode').onclick=startUpdate;document.getElementById('logout-form').addEventListener('submit',async e=>{{e.preventDefault();try{{await fetch('/logout',{{method:'POST',credentials:'same-origin'}});window.location.assign('/login')}}catch(err){{toast('Logout failed',err.message,'error')}}}});refreshSystem();
</script></body></html>'''
